import{_ as l,a0 as o,w as n,s as d,I as e,x as i,a1 as a,A as p,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"使用 pss 提升你的代碼搜索能力 | LCTT x X-CMD","titleTemplate":false,"description":"使用 pss 提升你的代碼搜索能力 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 pss 提升你的代碼搜索能力 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 pss 提升你的代碼搜索能力 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171222 Improve your code searching skills with pss","title":"使用 pss 提升你的代碼搜索能力","tag":"201712","desc":""},"relativePath":"201712/20171222 Improve your code searching skills with pss.md","filePath":"[post].md"}'),h={name:"201712/20171222 Improve your code searching skills with pss.md"};function g(k,s,u,b,c,f){const t=o("Link");return n(),d("div",null,[s[21]||(s[21]=e("h1",{id:"使用-pss-提升你的代碼搜索能力",tabindex:"-1"},[i("使用 pss 提升你的代碼搜索能力 "),e("a",{class:"header-anchor",href:"#使用-pss-提升你的代碼搜索能力","aria-label":"Permalink to “使用 pss 提升你的代碼搜索能力”"},"​")],-1)),s[22]||(s[22]=e("p",null,[e("img",{src:"https://fedoramagazine.org/wp-content/uploads/2017/12/pss-945x400.jpg",alt:""})],-1)),e("p",null,[s[1]||(s[1]=i("搜索代碼庫是開發者每天都要做的事情。從修改 bug 到學習新代碼，或者查看如何調用某個 API，能快速在代碼庫中導航的能力都是一大助力。幸運的是，我們有專門的工具來搜索代碼。",-1)),a(t,{href:"https://github.com/eliben/pss"},{default:p(()=>[...s[0]||(s[0]=[i("pss",-1)])]),_:1}),s[2]||(s[2]=i(" 就是其中一個工具，讓我們來看看如何安裝和使用它吧。",-1))]),s[23]||(s[23]=r('<h3 id="什麼是-pss" tabindex="-1">什麼是 pss？ <a class="header-anchor" href="#什麼是-pss" aria-label="Permalink to “什麼是 pss？”">​</a></h3><p><code>pss</code> 是一個幫你在源代碼文件中進行搜索的命令列工具。<code>pss</code> 遞歸地在目錄樹中進行搜索，它能自動根據文件名和後綴判斷哪些文件需要搜索，哪些文件不需搜索，並且會自動跳過那些你不會想搜索的目錄（比如 <code>.svn</code> 和 <code>.git</code>），還能用色彩渲染輸出以方便人們閲讀，以及其他很多功能。</p><h3 id="安裝-pss" tabindex="-1">安裝 pss <a class="header-anchor" href="#安裝-pss" aria-label="Permalink to “安裝 pss”">​</a></h3><p>使用下面命令在 Fedora 上安裝 <code>pss</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> $ dnf install pss</span></span></code></pre></div><p>安裝好後就能在終端調用 <code>pss</code> 了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> $ pss</span></span></code></pre></div><p>不帶參數調用 <code>pss</code> 或者帶上 <code>-h</code> 標誌會輸出詳細的使用説明。</p><h3 id="使用案例" tabindex="-1">使用案例 <a class="header-anchor" href="#使用案例" aria-label="Permalink to “使用案例”">​</a></h3><p>現在你安裝好 <code>pss</code> 了，下面來看一些例子吧。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> $ pss foo</span></span></code></pre></div><p>該命令只是簡單的搜索 <code>foo</code>。你也可以限制 <code>pss</code> 讓它只在 python 文件中搜索 <code>foo</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> $ pss foo --py</span></span></code></pre></div><p>還能在非 python 文件中搜索 <code>bar</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> $ pss bar --nopy</span></span></code></pre></div><p>而且，<code>pss</code> 支持大多數常見的源代碼文件類型，要獲取完整的支持列表，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pss --help-types</span></span></code></pre></div><p>你還能指定忽略某些目錄不進行搜索。默認情況下，<code>pss</code> 會忽略類似 <code>.git</code>，<code>__pycache__</code>，<code>.metadata</code> 等目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pss foo --py --ignore-dir=dist</span></span></code></pre></div><p>此外，<code>pss</code> 還能顯示搜索結果的上下文。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pss -A 5 foo</span></span></code></pre></div><p>會顯示匹配結果的後面 5 行內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pss -B 5 foo</span></span></code></pre></div><p>會顯示匹配結果的前面 5 行內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pss -C 5 foo</span></span></code></pre></div><p>會顯示匹配結果的前後各 5 行內容。</p>',26)),e("p",null,[s[4]||(s[4]=i("如果你想知道如何使用 ",-1)),s[5]||(s[5]=e("code",null,"pss ",-1)),s[6]||(s[6]=i(" 進行正則表達式搜索以及它的其他選項的話，可以在",-1)),a(t,{href:"https://github.com/eliben/pss/wiki/Usage-samples"},{default:p(()=>[...s[3]||(s[3]=[i("這裏",-1)])]),_:1}),s[7]||(s[7]=i("看到更多的例子。",-1))]),s[24]||(s[24]=e("hr",null,null,-1)),e("p",null,[s[9]||(s[9]=i("via: ",-1)),a(t,{href:"https://fedoramagazine.org/improve-code-searching-skills-pss/"},{default:p(()=>[...s[8]||(s[8]=[i("https://fedoramagazine.org/improve-code-searching-skills-pss/",-1)])]),_:1})]),e("p",null,[s[13]||(s[13]=i("作者：",-1)),a(t,{href:"https://fedoramagazine.org"},{default:p(()=>[...s[10]||(s[10]=[i("Clément Verna",-1)])]),_:1}),s[14]||(s[14]=i(" 譯者：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[11]||(s[11]=[i("lujun9972",-1)])]),_:1}),s[15]||(s[15]=i(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:p(()=>[...s[12]||(s[12]=[i("wxy",-1)])]),_:1})]),e("p",null,[s[18]||(s[18]=i("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[16]||(s[16]=[i("LCTT",-1)])]),_:1}),s[19]||(s[19]=i(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:p(()=>[...s[17]||(s[17]=[i("Linux中國",-1)])]),_:1}),s[20]||(s[20]=i(" 榮譽推出",-1))])])}const v=l(h,[["render",g]]);export{C as __pageData,v as default};
